diff --git a/pilot-task/src/normalize-email.mjs b/pilot-task/src/normalize-email.mjs
index 37219ea..7d3fd94 100644
--- a/pilot-task/src/normalize-email.mjs
+++ b/pilot-task/src/normalize-email.mjs
@@ -1,3 +1,38 @@
+const LOCAL_ATOM = "[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+";
+const LOCAL_PART_PATTERN = new RegExp(`^${LOCAL_ATOM}(?:\\.${LOCAL_ATOM})*$`);
+const DOMAIN_LABEL_PATTERN = /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$/;
+
 export function normalizeEmail(value) {
-  return String(value).trim().toLowerCase();
+  if (typeof value !== 'string') {
+    throw new TypeError('Email address must be a string');
+  }
+
+  const email = value.trim();
+  const atIndex = email.indexOf('@');
+
+  if (
+    email.length === 0
+    || email.length > 254
+    || /\s/u.test(email)
+    || atIndex <= 0
+    || atIndex !== email.lastIndexOf('@')
+    || atIndex === email.length - 1
+  ) {
+    throw new TypeError('Invalid email address');
+  }
+
+  const localPart = email.slice(0, atIndex);
+  const domain = email.slice(atIndex + 1);
+  const domainLabels = domain.split('.');
+
+  if (
+    localPart.length > 64
+    || domain.length > 253
+    || !LOCAL_PART_PATTERN.test(localPart)
+    || domainLabels.some((label) => !DOMAIN_LABEL_PATTERN.test(label))
+  ) {
+    throw new TypeError('Invalid email address');
+  }
+
+  return `${localPart}@${domain.toLowerCase()}`;
 }
